curl -s -X POST https://slack.com/api/conversations.list -d "token=<TOKEN>&types=public_channel&limit=1000" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        if 'deploy' in ch['name'].lower():
            print(ch['id'], ch['name'])
else:
    print('ERROR:', data.get('error'))
"

curl -s -X POST https://slack.com/api/users.list -d "token=<TOKEN>" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for u in data['members']:
        if 'priya' in u.get('real_name','').lower() or 'sharma' in u.get('real_name','').lower():
            print(u['id'], u['real_name'])
else:
    print('ERROR:', data.get('error'))
"

